Express + PostgreSQL 환경에서 Prisma를 세팅하고 기본 CRUD(Create, Read, Update, Delete)를 구현하는 전체 흐름을 예시 코드와 함께 정리하였습니다. (설치·마이그레이션 시에는 사용하는 Prisma 메이저 버전에 따라 CLI/생성 경로 안내가 다를 수 있으므로, 프로젝트에 설치된 Prisma 버전의 공식 문서 안내를 함께 참고해 주세요.)
핵심 파일
.env
prisma/schema.prisma
src/db/prisma.js
src/routes/items.routes.js
src/controllers/items.controller.js
src/app.js (라우터 및 에러 핸들러 연결)
1. Prisma 기본 세팅 흐름
① 패키지 설치 및 초기화
Express 프로젝트 루트에서 Prisma CLI와 클라이언트를 설치하고 초기화합니다.
npm install express dotenv @prisma/client
npm install -D prisma
npx prisma init --datasource-provider postgresql
prisma init을 실행하면 prisma/schema.prisma와 .env 파일이 생성됩니다.
② .env에 PostgreSQL 접속 문자열 설정
로컬 PostgreSQL에 연결할 주소와 생성해 둔 DB 이름을 넣습니다.
PORT=3000
DATABASE_URL="postgresql://postgres:비밀번호@localhost:5432/내_데이터베이스명?schema=public"
③ prisma/schema.prisma 모델 정의
MongoDB에서 mongoose 스키마를 정의하듯, 여기서는 테이블 구조를 model로 정의합니다.
generator client {
provider = "prisma-client-js"
}
datasource db {
provider = "postgresql"
url = env("DATABASE_URL")
}
model Item {
id Int @id @default(autoincrement())
name String
price Int
description String?
createdAt DateTime @default(now())
updatedAt DateTime @updatedAt
}
Int @id @default(autoincrement()): 자동 증가 기본키(SERIAL 계열)
String?: 물음표(?)가 붙으면 NULL 허용 컬럼
④ 마이그레이션 실행 및 클라이언트 생성
스키마 변경 내역을 실제 PostgreSQL 테이블로 반영하고 Prisma Client를 생성합니다.
npx prisma migrate dev --name init_item
npx prisma generate
2. Prisma Client 인스턴스 분리 (src/db/prisma.js)
Express 앱 전반에서 하나의 인스턴스를 재사용하도록 별도 파일로 분리해 둡니다.
const { PrismaClient } = require('@prisma/client');
const prisma = new PrismaClient();
module.exports = prisma;
3. Express CRUD 코드 예시
실무/학습 프로젝트에서는 보통 라우터(routes) → 컨트롤러(controllers)로 역할을 나누어 작성합니다. 아래는 Item 리소스의 기본 CRUD 예시입니다.
① src/routes/items.routes.js
const express = require('express');
const router = express.Router();
const {
createItem,
getItems,
getItemById,
updateItem,
deleteItem,
} = require('../controllers/items.controller');
router.post('/', createItem); // C: 생성
router.get('/', getItems); // R: 목록 조회
router.get('/:id', getItemById); // R: 단건 조회
router.patch('/:id', updateItem); // U: 수정
router.delete('/:id', deleteItem); // D: 삭제
module.exports = router;
② src/controllers/items.controller.js
URL 파라미터(req.params.id)는 문자열로 들어오므로, Int PK를 조회할 때는 숫자로 변환해야 합니다.
const prisma = require('../db/prisma');
// 1. Create (생성)
async function createItem(req, res, next) {
try {
const { name, price, description } = req.body;
if (!name || price === undefined) {
return res.status(400).json({ message: 'name과 price는 필수입니다.' });
}
const created = await prisma.item.create({
data: {
name,
price: Number(price),
description: description ?? null,
},
});
return res.status(201).json(created);
} catch (err) {
return next(err);
}
}
// 2. Read - 목록 조회
async function getItems(req, res, next) {
try {
const items = await prisma.item.findMany({
orderBy: { id: 'desc' },
});
return res.json(items);
} catch (err) {
return next(err);
}
}
// 2. Read - 단건 조회
async function getItemById(req, res, next) {
try {
const id = Number(req.params.id);
if (!Number.isInteger(id) || id <= 0) {
return res.status(400).json({ message: '유효하지 않은 ID입니다.' });
}
const item = await prisma.item.findUnique({
where: { id },
});
if (!item) {
return res.status(404).json({ message: '항목을 찾을 수 없습니다.' });
}
return res.json(item);
} catch (err) {
return next(err);
}
}
// 3. Update (수정)
async function updateItem(req, res, next) {
try {
const id = Number(req.params.id);
if (!Number.isInteger(id) || id <= 0) {
return res.status(400).json({ message: '유효하지 않은 ID입니다.' });
}
const { name, price, description } = req.body;
// 대상이 없을 때 update()는 에러(P2025)를 던지므로 먼저 확인하거나 에러 코드로 처리
const existing = await prisma.item.findUnique({ where: { id } });
if (!existing) {
return res.status(404).json({ message: '수정할 항목이 없습니다.' });
}
const updated = await prisma.item.update({
where: { id },
data: {
...(name !== undefined && { name }),
...(price !== undefined && { price: Number(price) }),
...(description !== undefined && { description }),
},
});
return res.json(updated);
} catch (err) {
return next(err);
}
}
// 4. Delete (삭제)
async function deleteItem(req, res, next) {
try {
const id = Number(req.params.id);
if (!Number.isInteger(id) || id <= 0) {
return res.status(400).json({ message: '유효하지 않은 ID입니다.' });
}
const existing = await prisma.item.findUnique({ where: { id } });
if (!existing) {
return res.status(404).json({ message: '삭제할 항목이 없습니다.' });
}
await prisma.item.delete({
where: { id },
});
return res.status(204).send();
} catch (err) {
return next(err);
}
}
module.exports = {
createItem,
getItems,
getItemById,
updateItem,
deleteItem,
};
③ src/app.js (라우터 및 에러 핸들러 연결)
require('dotenv').config();
const express = require('express');
const itemsRouter = require('./routes/items.routes');
const app = express();
const PORT = process.env.PORT || 3000;
app.use(express.json());
app.get('/', (req, res) => {
res.json({ message: 'Express + Prisma + PostgreSQL API running' });
});
app.use('/items', itemsRouter);
// 공통 에러 핸들러
app.use((err, req, res, next) => {
console.error(err);
res.status(500).json({ message: '서버 내부 오류가 발생했습니다.' });
});
app.listen(PORT, () => {
console.log(`Server listening on http://localhost:${PORT}`);
});
4. MongoDB(mongoose)에서 넘어올 때 주의할 점
존재하지 않는 레코드 수정/삭제 시 동작: prisma.item.update()나 prisma.item.delete()는 대상 행이 없으면 예외를 발생시킵니다. 그래서 위 예시처럼 먼저 존재 여부를 확인하거나, Prisma 고유 에러 코드(err.code === 'P2025')를 분기 처리하는 습관을 들이면 좋습니다.
스키마를 고쳤다면 migrate dev를 다시 실행: schema.prisma에 필드를 추가하거나 수정한 뒤 마이그레이션을 돌리지 않으면 실제 DB 테이블과 코드가 어긋납니다.
Prisma ORM Setup, Migrations & CRUD Tutorial
이 영상은 Prisma 설치부터 스키마 작성, 마이그레이션 실행, CRUD 쿼리 흐름까지 전반적인 과정을 시각적으로 따라가며 익히기에 적합합니다.
